insert into public.dl_books (title, author, seeded) values
 ('The 7 Habits of Highly Effective People','Stephen R. Covey',true),('Atomic Habits','James Clear',true),('Extreme Ownership','Jocko Willink & Leif Babin',true);
insert into public.dl_quotes (kind, body, citation, speaker, speaker_role, talk_title, url, conference, book_id, source_note, seeded)
select r.kind, r.body, r.citation, r.speaker, r.speaker_role, r.talk_title, r.url, r.conference, b.id, r.source_note, true
from jsonb_to_recordset($seed$[{"kind": "scripture", "body": "Believe in God; believe that he is, and that he created all things, both in heaven and in earth; believe that he has all wisdom, and all power, both in heaven and in earth; believe that man doth not comprehend all the things which the Lord can comprehend.", "citation": "Mosiah 4:9", "url": "https://www.churchofjesuschrist.org/study/scriptures/bofm/mosiah/4?lang=eng&id=p9#p9", "source_note": "Book of Mormon (public-domain text, Project Gutenberg eBook #17; checked against churchofjesuschrist.org)", "ord": 0}, {"kind": "scripture", "body": "Pray in your families unto the Father, always in my name, that your wives and your children may be blessed.", "citation": "3 Nephi 18:21", "url": "https://www.churchofjesuschrist.org/study/scriptures/bofm/3-ne/18?lang=eng&id=p21#p21", "source_note": "Book of Mormon (public-domain text, Project Gutenberg eBook #17; checked against churchofjesuschrist.org)", "ord": 1}, {"kind": "scripture", "body": "And now my son, Shiblon, I would that ye should remember, that as much as ye shall put your trust in God even so much ye shall be delivered out of your trials, and your troubles, and your afflictions, and ye shall be lifted up at the last day.", "citation": "Alma 38:5", "url": "https://www.churchofjesuschrist.org/study/scriptures/bofm/alma/38?lang=eng&id=p5#p5", "source_note": "Book of Mormon (public-domain text, Project Gutenberg eBook #17; checked against churchofjesuschrist.org)", "ord": 2}, {"kind": "scripture", "body": "And when ye shall receive these things, I would exhort you that ye would ask God, the Eternal Father, in the name of Christ, if these things are not true; and if ye shall ask with a sincere heart, with real intent, having faith in Christ, he will manifest the truth of it unto you, by the power of the Holy Ghost.", "citation": "Moroni 10:4", "url": "https://www.churchofjesuschrist.org/study/scriptures/bofm/moro/10?lang=eng&id=p4#p4", "source_note": "Book of Mormon (public-domain text, Project Gutenberg eBook #17; checked against churchofjesuschrist.org)", "ord": 3}, {"kind": "scripture", "body": "Behold, my soul delighteth in the things of the Lord; and my heart pondereth continually upon the things which I have seen and heard.", "citation": "2 Nephi 4:16", "url": "https://www.churchofjesuschrist.org/study/scriptures/bofm/2-ne/4?lang=eng&id=p16#p16", "source_note": "Book of Mormon (public-domain text, Project Gutenberg eBook #17; checked against churchofjesuschrist.org)", "ord": 4}, {"kind": "scripture", "body": "Counsel with the Lord in all thy doings, and he will direct thee for good; yea, when thou liest down at night lie down unto the Lord, that he may watch over you in your sleep; and when thou risest in the morning let thy heart be full of thanks unto God; and if ye do these things, ye shall be lifted up at the last day.", "citation": "Alma 37:37", "url": "https://www.churchofjesuschrist.org/study/scriptures/bofm/alma/37?lang=eng&id=p37#p37", "source_note": "Book of Mormon (public-domain text, Project Gutenberg eBook #17; checked against churchofjesuschrist.org)", "ord": 5}, {"kind": "scripture", "body": "Now ye may suppose that this is foolishness in me; but behold I say unto you, that by small and simple things are great things brought to pass; and small means in many instances doth confound the wise.", "citation": "Alma 37:6", "url": "https://www.churchofjesuschrist.org/study/scriptures/bofm/alma/37?lang=eng&id=p6#p6", "source_note": "Book of Mormon (public-domain text, Project Gutenberg eBook #17; checked against churchofjesuschrist.org)", "ord": 6}, {"kind": "scripture", "body": "For we labor diligently to write, to persuade our children, and also our brethren, to believe in Christ, and to be reconciled to God; for we know that it is by grace that we are saved, after all we can do.", "citation": "2 Nephi 25:23", "url": "https://www.churchofjesuschrist.org/study/scriptures/bofm/2-ne/25?lang=eng&id=p23#p23", "source_note": "Book of Mormon (public-domain text, Project Gutenberg eBook #17; checked against churchofjesuschrist.org)", "ord": 7}, {"kind": "scripture", "body": "Therefore I would that ye should be perfect even as I, or your Father who is in heaven is perfect.", "citation": "3 Nephi 12:48", "url": "https://www.churchofjesuschrist.org/study/scriptures/bofm/3-ne/12?lang=eng&id=p48#p48", "source_note": "Book of Mormon (public-domain text, Project Gutenberg eBook #17; checked against churchofjesuschrist.org)", "ord": 8}, {"kind": "scripture", "body": "Do not suppose, because it has been spoken concerning restoration, that ye shall be restored from sin to happiness. Behold, I say unto you, wickedness never was happiness.", "citation": "Alma 41:10", "url": "https://www.churchofjesuschrist.org/study/scriptures/bofm/alma/41?lang=eng&id=p10#p10", "source_note": "Book of Mormon (public-domain text, Project Gutenberg eBook #17; checked against churchofjesuschrist.org)", "ord": 9}, {"kind": "scripture", "body": "And now I would that ye should be humble, and be submissive and gentle; easy to be entreated; full of patience and long-suffering; being temperate in all things; being diligent in keeping the commandments of God at all times; asking for whatsoever things ye stand in need, both spiritual and temporal; always returning thanks unto God for whatsoever things ye do receive.", "citation": "Alma 7:23", "url": "https://www.churchofjesuschrist.org/study/scriptures/bofm/alma/7?lang=eng&id=p23#p23", "source_note": "Book of Mormon (public-domain text, Project Gutenberg eBook #17; checked against churchofjesuschrist.org)", "ord": 10}, {"kind": "scripture", "body": "And when he had said these words, he wept, and the multitude bare record of it, and he took their little children, one by one, and blessed them, and prayed unto the Father for them.", "citation": "3 Nephi 17:21", "url": "https://www.churchofjesuschrist.org/study/scriptures/bofm/3-ne/17?lang=eng&id=p21#p21", "source_note": "Book of Mormon (public-domain text, Project Gutenberg eBook #17; checked against churchofjesuschrist.org)", "ord": 11}, {"kind": "scripture", "body": "Therefore let your light so shine before this people, that they may see your good works and glorify your Father who is in heaven.", "citation": "3 Nephi 12:16", "url": "https://www.churchofjesuschrist.org/study/scriptures/bofm/3-ne/12?lang=eng&id=p16#p16", "source_note": "Book of Mormon (public-domain text, Project Gutenberg eBook #17; checked against churchofjesuschrist.org)", "ord": 12}, {"kind": "scripture", "body": "And there were no envyings, nor strifes, nor tumults, nor whoredoms, nor lyings, nor murders, nor any manner of lasciviousness; and surely there could not be a happier people among all the people who had been created by the hand of God.", "citation": "4 Nephi 1:16", "url": "https://www.churchofjesuschrist.org/study/scriptures/bofm/4-ne/1?lang=eng&id=p16#p16", "source_note": "Book of Mormon (public-domain text, Project Gutenberg eBook #17; checked against churchofjesuschrist.org)", "ord": 13}, {"kind": "scripture", "body": "For the natural man is an enemy to God, and has been from the fall of Adam, and will be, forever and ever, unless he yields to the enticings of the Holy Spirit, and putteth off the natural man and becometh a saint through the atonement of Christ the Lord, and becometh as a child, submissive, meek, humble, patient, full of love, willing to submit to all things which the Lord seeth fit to inflict upon him, even as a child doth submit to his father.", "citation": "Mosiah 3:19", "url": "https://www.churchofjesuschrist.org/study/scriptures/bofm/mosiah/3?lang=eng&id=p19#p19", "source_note": "Book of Mormon (public-domain text, Project Gutenberg eBook #17; checked against churchofjesuschrist.org)", "ord": 14}, {"kind": "scripture", "body": "And what is it that ye shall hope for? Behold I say unto you that ye shall have hope through the atonement of Christ and the power of his resurrection, to be raised unto life eternal, and this because of your faith in him according to the promise.", "citation": "Moroni 7:41", "url": "https://www.churchofjesuschrist.org/study/scriptures/bofm/moro/7?lang=eng&id=p41#p41", "source_note": "Book of Mormon (public-domain text, Project Gutenberg eBook #17; checked against churchofjesuschrist.org)", "ord": 15}, {"kind": "scripture", "body": "Use boldness, but not overbearance; and also see that ye bridle all your passions, that ye may be filled with love; see that ye refrain from idleness.", "citation": "Alma 38:12", "url": "https://www.churchofjesuschrist.org/study/scriptures/bofm/alma/38?lang=eng&id=p12#p12", "source_note": "Book of Mormon (public-domain text, Project Gutenberg eBook #17; checked against churchofjesuschrist.org)", "ord": 16}, {"kind": "scripture", "body": "O Lord, I have trusted in thee, and I will trust in thee forever. I will not put my trust in the arm of flesh; for I know that cursed is he that putteth his trust in the arm of flesh. Yea, cursed is he that putteth his trust in man or maketh flesh his arm.", "citation": "2 Nephi 4:34", "url": "https://www.churchofjesuschrist.org/study/scriptures/bofm/2-ne/4?lang=eng&id=p34#p34", "source_note": "Book of Mormon (public-domain text, Project Gutenberg eBook #17; checked against churchofjesuschrist.org)", "ord": 17}, {"kind": "scripture", "body": "And they were all young men, and they were exceedingly valiant for courage, and also for strength and activity; but behold, this was not all—they were men who were true at all times in whatsoever thing they were entrusted.", "citation": "Alma 53:20", "url": "https://www.churchofjesuschrist.org/study/scriptures/bofm/alma/53?lang=eng&id=p20#p20", "source_note": "Book of Mormon (public-domain text, Project Gutenberg eBook #17; checked against churchofjesuschrist.org)", "ord": 18}, {"kind": "scripture", "body": "And whatsoever ye shall ask the Father in my name, which is right, believing that ye shall receive, behold it shall be given unto you.", "citation": "3 Nephi 18:20", "url": "https://www.churchofjesuschrist.org/study/scriptures/bofm/3-ne/18?lang=eng&id=p20#p20", "source_note": "Book of Mormon (public-domain text, Project Gutenberg eBook #17; checked against churchofjesuschrist.org)", "ord": 19}, {"kind": "scripture", "body": "Blessed art thou, Nephi, for those things which thou hast done; for I have beheld how thou hast with unwearyingness declared the word, which I have given unto thee, unto this people. And thou hast not feared them, and hast not sought thine own life, but hast sought my will, and to keep my commandments.", "citation": "Helaman 10:4", "url": "https://www.churchofjesuschrist.org/study/scriptures/bofm/hel/10?lang=eng&id=p4#p4", "source_note": "Book of Mormon (public-domain text, Project Gutenberg eBook #17; checked against churchofjesuschrist.org)", "ord": 20}, {"kind": "scripture", "body": "And now, O my son Helaman, behold, thou art in thy youth, and therefore, I beseech of thee that thou wilt hear my words and learn of me; for I do know that whosoever shall put their trust in God shall be supported in their trials, and their troubles, and their afflictions, and shall be lifted up at the last day.", "citation": "Alma 36:3", "url": "https://www.churchofjesuschrist.org/study/scriptures/bofm/alma/36?lang=eng&id=p3#p3", "source_note": "Book of Mormon (public-domain text, Project Gutenberg eBook #17; checked against churchofjesuschrist.org)", "ord": 21}, {"kind": "scripture", "body": "And now, my sons, remember, remember that it is upon the rock of our Redeemer, who is Christ, the Son of God, that ye must build your foundation; that when the devil shall send forth his mighty winds, yea, his shafts in the whirlwind, yea, when all his hail and his mighty storm shall beat upon you, it shall have no power over you to drag you down to the gulf of misery and endless wo, because of the rock upon which ye are built, which is a sure foundation, a foundation whereon if men build they cannot fall.", "citation": "Helaman 5:12", "url": "https://www.churchofjesuschrist.org/study/scriptures/bofm/hel/5?lang=eng&id=p12#p12", "source_note": "Book of Mormon (public-domain text, Project Gutenberg eBook #17; checked against churchofjesuschrist.org)", "ord": 22}, {"kind": "scripture", "body": "And now, I, Moroni, would speak somewhat concerning these things; I would show unto the world that faith is things which are hoped for and not seen; wherefore, dispute not because ye see not, for ye receive no witness until after the trial of your faith.", "citation": "Ether 12:6", "url": "https://www.churchofjesuschrist.org/study/scriptures/bofm/ether/12?lang=eng&id=p6#p6", "source_note": "Book of Mormon (public-domain text, Project Gutenberg eBook #17; checked against churchofjesuschrist.org)", "ord": 23}, {"kind": "scripture", "body": "And thus we see that the commandments of God must be fulfilled. And if it so be that the children of men keep the commandments of God he doth nourish them, and strengthen them, and provide means whereby they can accomplish the thing which he has commanded them; wherefore, he did provide means for us while we did sojourn in the wilderness.", "citation": "1 Nephi 17:3", "url": "https://www.churchofjesuschrist.org/study/scriptures/bofm/1-ne/17?lang=eng&id=p3#p3", "source_note": "Book of Mormon (public-domain text, Project Gutenberg eBook #17; checked against churchofjesuschrist.org)", "ord": 24}, {"kind": "scripture", "body": "Yea, come unto Christ, and be perfected in him, and deny yourselves of all ungodliness; and if ye shall deny yourselves of all ungodliness and love God with all your might, mind and strength, then is his grace sufficient for you, that by his grace ye may be perfect in Christ; and if by the grace of God ye are perfect in Christ, ye can in nowise deny the power of God.", "citation": "Moroni 10:32", "url": "https://www.churchofjesuschrist.org/study/scriptures/bofm/moro/10?lang=eng&id=p32#p32", "source_note": "Book of Mormon (public-domain text, Project Gutenberg eBook #17; checked against churchofjesuschrist.org)", "ord": 25}, {"kind": "scripture", "body": "And now, my beloved brethren, I perceive that ye ponder still in your hearts; and it grieveth me that I must speak concerning this thing. For if ye would hearken unto the Spirit which teacheth a man to pray ye would know that ye must pray; for the evil spirit teacheth not a man to pray, but teacheth him that he must not pray.", "citation": "2 Nephi 32:8", "url": "https://www.churchofjesuschrist.org/study/scriptures/bofm/2-ne/32?lang=eng&id=p8#p8", "source_note": "Book of Mormon (public-domain text, Project Gutenberg eBook #17; checked against churchofjesuschrist.org)", "ord": 26}, {"kind": "scripture", "body": "And now as I said concerning faith—faith is not to have a perfect knowledge of things; therefore if ye have faith ye hope for things which are not seen, which are true.", "citation": "Alma 32:21", "url": "https://www.churchofjesuschrist.org/study/scriptures/bofm/alma/32?lang=eng&id=p21#p21", "source_note": "Book of Mormon (public-domain text, Project Gutenberg eBook #17; checked against churchofjesuschrist.org)", "ord": 27}, {"kind": "scripture", "body": "And we talk of Christ, we rejoice in Christ, we preach of Christ, we prophesy of Christ, and we write according to our prophecies, that our children may know to what source they may look for a remission of their sins.", "citation": "2 Nephi 25:26", "url": "https://www.churchofjesuschrist.org/study/scriptures/bofm/2-ne/25?lang=eng&id=p26#p26", "source_note": "Book of Mormon (public-domain text, Project Gutenberg eBook #17; checked against churchofjesuschrist.org)", "ord": 28}, {"kind": "scripture", "body": "And I said unto him: I know that he loveth his children; nevertheless, I do not know the meaning of all things.", "citation": "1 Nephi 11:17", "url": "https://www.churchofjesuschrist.org/study/scriptures/bofm/1-ne/11?lang=eng&id=p17#p17", "source_note": "Book of Mormon (public-domain text, Project Gutenberg eBook #17; checked against churchofjesuschrist.org)", "ord": 29}, {"kind": "scripture", "body": "Ask, and it shall be given unto you; seek, and ye shall find; knock, and it shall be opened unto you.", "citation": "3 Nephi 14:7", "url": "https://www.churchofjesuschrist.org/study/scriptures/bofm/3-ne/14?lang=eng&id=p7#p7", "source_note": "Book of Mormon (public-domain text, Project Gutenberg eBook #17; checked against churchofjesuschrist.org)", "ord": 30}, {"kind": "scripture", "body": "Yea, I know that I am nothing; as to my strength I am weak; therefore I will not boast of myself, but I will boast of my God, for in his strength I can do all things; yea, behold, many mighty miracles we have wrought in this land, for which we will praise his name forever.", "citation": "Alma 26:12", "url": "https://www.churchofjesuschrist.org/study/scriptures/bofm/alma/26?lang=eng&id=p12#p12", "source_note": "Book of Mormon (public-domain text, Project Gutenberg eBook #17; checked against churchofjesuschrist.org)", "ord": 31}, {"kind": "scripture", "body": "And now behold, I ask of you, my brethren of the church, have ye spiritually been born of God? Have ye received his image in your countenances? Have ye experienced this mighty change in your hearts?", "citation": "Alma 5:14", "url": "https://www.churchofjesuschrist.org/study/scriptures/bofm/alma/5?lang=eng&id=p14#p14", "source_note": "Book of Mormon (public-domain text, Project Gutenberg eBook #17; checked against churchofjesuschrist.org)", "ord": 32}, {"kind": "scripture", "body": "And I soon go to the place of my rest, which is with my Redeemer; for I know that in him I shall rest. And I rejoice in the day when my mortal shall put on immortality, and shall stand before him; then shall I see his face with pleasure, and he will say unto me: Come unto me, ye blessed, there is a place prepared for you in the mansions of my Father. Amen.", "citation": "Enos 1:27", "url": "https://www.churchofjesuschrist.org/study/scriptures/bofm/enos/1?lang=eng&id=p27#p27", "source_note": "Book of Mormon (public-domain text, Project Gutenberg eBook #17; checked against churchofjesuschrist.org)", "ord": 33}, {"kind": "scripture", "body": "And when the Jews heard these things they were angry with him; yea, even as with the prophets of old, whom they had cast out, and stoned, and slain; and they also sought his life, that they might take it away. But behold, I, Nephi, will show unto you that the tender mercies of the Lord are over all those whom he hath chosen, because of their faith, to make them mighty even unto the power of deliverance.", "citation": "1 Nephi 1:20", "url": "https://www.churchofjesuschrist.org/study/scriptures/bofm/1-ne/1?lang=eng&id=p20#p20", "source_note": "Book of Mormon (public-domain text, Project Gutenberg eBook #17; checked against churchofjesuschrist.org)", "ord": 34}, {"kind": "scripture", "body": "But before ye seek for riches, seek ye for the kingdom of God.", "citation": "Jacob 2:18", "url": "https://www.churchofjesuschrist.org/study/scriptures/bofm/jacob/2?lang=eng&id=p18#p18", "source_note": "Book of Mormon (public-domain text, Project Gutenberg eBook #17; checked against churchofjesuschrist.org)", "ord": 35}, {"kind": "scripture", "body": "O that cunning plan of the evil one! O the vainness, and the frailties, and the foolishness of men! When they are learned they think they are wise, and they hearken not unto the counsel of God, for they set it aside, supposing they know of themselves, wherefore, their wisdom is foolishness and it profiteth them not. And they shall perish.", "citation": "2 Nephi 9:28", "url": "https://www.churchofjesuschrist.org/study/scriptures/bofm/2-ne/9?lang=eng&id=p28#p28", "source_note": "Book of Mormon (public-domain text, Project Gutenberg eBook #17; checked against churchofjesuschrist.org)", "ord": 36}, {"kind": "scripture", "body": "But this much I can tell you, that if ye do not watch yourselves, and your thoughts, and your words, and your deeds, and observe the commandments of God, and continue in the faith of what ye have heard concerning the coming of our Lord, even unto the end of your lives, ye must perish. And now, O man, remember, and perish not.", "citation": "Mosiah 4:30", "url": "https://www.churchofjesuschrist.org/study/scriptures/bofm/mosiah/4?lang=eng&id=p30#p30", "source_note": "Book of Mormon (public-domain text, Project Gutenberg eBook #17; checked against churchofjesuschrist.org)", "ord": 37}, {"kind": "scripture", "body": "Now, we will compare the word unto a seed. Now, if ye give place, that a seed may be planted in your heart, behold, if it be a true seed, or a good seed, if ye do not cast it out by your unbelief, that ye will resist the Spirit of the Lord, behold, it will begin to swell within your breasts; and when you feel these swelling motions, ye will begin to say within yourselves—It must needs be that this is a good seed, or that the word is good, for it beginneth to enlarge my soul; yea, it beginneth to enlighten my understanding, yea, it beginneth to be delicious to me.", "citation": "Alma 32:28", "url": "https://www.churchofjesuschrist.org/study/scriptures/bofm/alma/32?lang=eng&id=p28#p28", "source_note": "Book of Mormon (public-domain text, Project Gutenberg eBook #17; checked against churchofjesuschrist.org)", "ord": 38}, {"kind": "scripture", "body": "For behold, the Spirit of Christ is given to every man, that he may know good from evil; wherefore, I show unto you the way to judge; for every thing which inviteth to do good, and to persuade to believe in Christ, is sent forth by the power and gift of Christ; wherefore ye may know with a perfect knowledge it is of God.", "citation": "Moroni 7:16", "url": "https://www.churchofjesuschrist.org/study/scriptures/bofm/moro/7?lang=eng&id=p16#p16", "source_note": "Book of Mormon (public-domain text, Project Gutenberg eBook #17; checked against churchofjesuschrist.org)", "ord": 39}, {"kind": "scripture", "body": "And he shall go forth, suffering pains and afflictions and temptations of every kind; and this that the word might be fulfilled which saith he will take upon him the pains and the sicknesses of his people.", "citation": "Alma 7:11", "url": "https://www.churchofjesuschrist.org/study/scriptures/bofm/alma/7?lang=eng&id=p11#p11", "source_note": "Book of Mormon (public-domain text, Project Gutenberg eBook #17; checked against churchofjesuschrist.org)", "ord": 40}, {"kind": "scripture", "body": "And he will take upon him death, that he may loose the bands of death which bind his people; and he will take upon him their infirmities, that his bowels may be filled with mercy, according to the flesh, that he may know according to the flesh how to succor his people according to their infirmities.", "citation": "Alma 7:12", "url": "https://www.churchofjesuschrist.org/study/scriptures/bofm/alma/7?lang=eng&id=p12#p12", "source_note": "Book of Mormon (public-domain text, Project Gutenberg eBook #17; checked against churchofjesuschrist.org)", "ord": 41}, {"kind": "scripture", "body": "Adam fell that men might be; and men are, that they might have joy.", "citation": "2 Nephi 2:25", "url": "https://www.churchofjesuschrist.org/study/scriptures/bofm/2-ne/2?lang=eng&id=p25#p25", "source_note": "Book of Mormon (public-domain text, Project Gutenberg eBook #17; checked against churchofjesuschrist.org)", "ord": 42}, {"kind": "scripture", "body": "Wherefore, brethren, seek not to counsel the Lord, but to take counsel from his hand. For behold, ye yourselves know that he counseleth in wisdom, and in justice, and in great mercy, over all his works.", "citation": "Jacob 4:10", "url": "https://www.churchofjesuschrist.org/study/scriptures/bofm/jacob/4?lang=eng&id=p10#p10", "source_note": "Book of Mormon (public-domain text, Project Gutenberg eBook #17; checked against churchofjesuschrist.org)", "ord": 43}, {"kind": "scripture", "body": "And I did read many things unto them which were written in the books of Moses; but that I might more fully persuade them to believe in the Lord their Redeemer I did read unto them that which was written by the prophet Isaiah; for I did liken all scriptures unto us, that it might be for our profit and learning.", "citation": "1 Nephi 19:23", "url": "https://www.churchofjesuschrist.org/study/scriptures/bofm/1-ne/19?lang=eng&id=p23#p23", "source_note": "Book of Mormon (public-domain text, Project Gutenberg eBook #17; checked against churchofjesuschrist.org)", "ord": 44}, {"kind": "scripture", "body": "And by the power of the Holy Ghost ye may know the truth of all things.", "citation": "Moroni 10:5", "url": "https://www.churchofjesuschrist.org/study/scriptures/bofm/moro/10?lang=eng&id=p5#p5", "source_note": "Book of Mormon (public-domain text, Project Gutenberg eBook #17; checked against churchofjesuschrist.org)", "ord": 45}, {"kind": "scripture", "body": "And I will also ease the burdens which are put upon your shoulders, that even you cannot feel them upon your backs, even while you are in bondage; and this will I do that ye may stand as witnesses for me hereafter, and that ye may know of a surety that I, the Lord God, do visit my people in their afflictions.", "citation": "Mosiah 24:14", "url": "https://www.churchofjesuschrist.org/study/scriptures/bofm/mosiah/24?lang=eng&id=p14#p14", "source_note": "Book of Mormon (public-domain text, Project Gutenberg eBook #17; checked against churchofjesuschrist.org)", "ord": 46}, {"kind": "scripture", "body": "And behold, I tell you these things that ye may learn wisdom; that ye may learn that when ye are in the service of your fellow beings ye are only in the service of your God.", "citation": "Mosiah 2:17", "url": "https://www.churchofjesuschrist.org/study/scriptures/bofm/mosiah/2?lang=eng&id=p17#p17", "source_note": "Book of Mormon (public-domain text, Project Gutenberg eBook #17; checked against churchofjesuschrist.org)", "ord": 47}, {"kind": "scripture", "body": "Now they never had fought, yet they did not fear death; and they did think more upon the liberty of their fathers than they did upon their lives; yea, they had been taught by their mothers, that if they did not doubt, God would deliver them.", "citation": "Alma 56:47", "url": "https://www.churchofjesuschrist.org/study/scriptures/bofm/alma/56?lang=eng&id=p47#p47", "source_note": "Book of Mormon (public-domain text, Project Gutenberg eBook #17; checked against churchofjesuschrist.org)", "ord": 48}, {"kind": "scripture", "body": "O be wise; what can I say more?", "citation": "Jacob 6:12", "url": "https://www.churchofjesuschrist.org/study/scriptures/bofm/jacob/6?lang=eng&id=p12#p12", "source_note": "Book of Mormon (public-domain text, Project Gutenberg eBook #17; checked against churchofjesuschrist.org)", "ord": 49}, {"kind": "scripture", "body": "Angels speak by the power of the Holy Ghost; wherefore, they speak the words of Christ. Wherefore, I said unto you, feast upon the words of Christ; for behold, the words of Christ will tell you all things what ye should do.", "citation": "2 Nephi 32:3", "url": "https://www.churchofjesuschrist.org/study/scriptures/bofm/2-ne/32?lang=eng&id=p3#p3", "source_note": "Book of Mormon (public-domain text, Project Gutenberg eBook #17; checked against churchofjesuschrist.org)", "ord": 50}, {"kind": "scripture", "body": "And moreover, I would desire that ye should consider on the blessed and happy state of those that keep the commandments of God. For behold, they are blessed in all things, both temporal and spiritual; and if they hold out faithful to the end they are received into heaven, that thereby they may dwell with God in a state of never-ending happiness. O remember, remember that these things are true; for the Lord God hath spoken it.", "citation": "Mosiah 2:41", "url": "https://www.churchofjesuschrist.org/study/scriptures/bofm/mosiah/2?lang=eng&id=p41#p41", "source_note": "Book of Mormon (public-domain text, Project Gutenberg eBook #17; checked against churchofjesuschrist.org)", "ord": 51}, {"kind": "scripture", "body": "But charity is the pure love of Christ, and it endureth forever; and whoso is found possessed of it at the last day, it shall be well with him.", "citation": "Moroni 7:47", "url": "https://www.churchofjesuschrist.org/study/scriptures/bofm/moro/7?lang=eng&id=p47#p47", "source_note": "Book of Mormon (public-domain text, Project Gutenberg eBook #17; checked against churchofjesuschrist.org)", "ord": 52}, {"kind": "scripture", "body": "And after ye have obtained a hope in Christ ye shall obtain riches, if ye seek them; and ye will seek them for the intent to do good—to clothe the naked, and to feed the hungry, and to liberate the captive, and administer relief to the sick and the afflicted.", "citation": "Jacob 2:19", "url": "https://www.churchofjesuschrist.org/study/scriptures/bofm/jacob/2?lang=eng&id=p19#p19", "source_note": "Book of Mormon (public-domain text, Project Gutenberg eBook #17; checked against churchofjesuschrist.org)", "ord": 53}, {"kind": "scripture", "body": "And if men come unto me I will show unto them their weakness. I give unto men weakness that they may be humble; and my grace is sufficient for all men that humble themselves before me; for if they humble themselves before me, and have faith in me, then will I make weak things become strong unto them.", "citation": "Ether 12:27", "url": "https://www.churchofjesuschrist.org/study/scriptures/bofm/ether/12?lang=eng&id=p27#p27", "source_note": "Book of Mormon (public-domain text, Project Gutenberg eBook #17; checked against churchofjesuschrist.org)", "ord": 54}, {"kind": "scripture", "body": "And he commanded them that there should be no contention one with another, but that they should look forward with one eye, having one faith and one baptism, having their hearts knit together in unity and in love one towards another.", "citation": "Mosiah 18:21", "url": "https://www.churchofjesuschrist.org/study/scriptures/bofm/mosiah/18?lang=eng&id=p21#p21", "source_note": "Book of Mormon (public-domain text, Project Gutenberg eBook #17; checked against churchofjesuschrist.org)", "ord": 55}, {"kind": "scripture", "body": "O, remember, my son, and learn wisdom in thy youth; yea, learn in thy youth to keep the commandments of God.", "citation": "Alma 37:35", "url": "https://www.churchofjesuschrist.org/study/scriptures/bofm/alma/37?lang=eng&id=p35#p35", "source_note": "Book of Mormon (public-domain text, Project Gutenberg eBook #17; checked against churchofjesuschrist.org)", "ord": 56}, {"kind": "scripture", "body": "And know ye that ye shall be judges of this people, according to the judgment which I shall give unto you, which shall be just. Therefore, what manner of men ought ye to be? Verily I say unto you, even as I am.", "citation": "3 Nephi 27:27", "url": "https://www.churchofjesuschrist.org/study/scriptures/bofm/3-ne/27?lang=eng&id=p27#p27", "source_note": "Book of Mormon (public-domain text, Project Gutenberg eBook #17; checked against churchofjesuschrist.org)", "ord": 57}, {"kind": "scripture", "body": "Wherefore, my beloved brethren, pray unto the Father with all the energy of heart, that ye may be filled with this love, which he hath bestowed upon all who are true followers of his Son, Jesus Christ; that ye may become the sons of God; that when he shall appear we shall be like him, for we shall see him as he is; that we may have this hope; that we may be purified even as he is pure. Amen.", "citation": "Moroni 7:48", "url": "https://www.churchofjesuschrist.org/study/scriptures/bofm/moro/7?lang=eng&id=p48#p48", "source_note": "Book of Mormon (public-domain text, Project Gutenberg eBook #17; checked against churchofjesuschrist.org)", "ord": 58}, {"kind": "scripture", "body": "And charity suffereth long, and is kind, and envieth not, and is not puffed up, seeketh not her own, is not easily provoked, thinketh no evil, and rejoiceth not in iniquity but rejoiceth in the truth, beareth all things, believeth all things, hopeth all things, endureth all things.", "citation": "Moroni 7:45", "url": "https://www.churchofjesuschrist.org/study/scriptures/bofm/moro/7?lang=eng&id=p45#p45", "source_note": "Book of Mormon (public-domain text, Project Gutenberg eBook #17; checked against churchofjesuschrist.org)", "ord": 59}, {"kind": "scripture", "body": "Wherefore, men are free according to the flesh; and all things are given them which are expedient unto man. And they are free to choose liberty and eternal life, through the great Mediator of all men, or to choose captivity and death, according to the captivity and power of the devil; for he seeketh that all men might be miserable like unto himself.", "citation": "2 Nephi 2:27", "url": "https://www.churchofjesuschrist.org/study/scriptures/bofm/2-ne/2?lang=eng&id=p27#p27", "source_note": "Book of Mormon (public-domain text, Project Gutenberg eBook #17; checked against churchofjesuschrist.org)", "ord": 60}, {"kind": "scripture", "body": "And behold, I am the light and the life of the world; and I have drunk out of that bitter cup which the Father hath given me, and have glorified the Father in taking upon me the sins of the world, in the which I have suffered the will of the Father in all things from the beginning.", "citation": "3 Nephi 11:11", "url": "https://www.churchofjesuschrist.org/study/scriptures/bofm/3-ne/11?lang=eng&id=p11#p11", "source_note": "Book of Mormon (public-domain text, Project Gutenberg eBook #17; checked against churchofjesuschrist.org)", "ord": 61}, {"kind": "scripture", "body": "But behold, I say unto you that ye must pray always, and not faint; that ye must not perform any thing unto the Lord save in the first place ye shall pray unto the Father in the name of Christ, that he will consecrate thy performance unto thee, that thy performance may be for the welfare of thy soul.", "citation": "2 Nephi 32:9", "url": "https://www.churchofjesuschrist.org/study/scriptures/bofm/2-ne/32?lang=eng&id=p9#p9", "source_note": "Book of Mormon (public-domain text, Project Gutenberg eBook #17; checked against churchofjesuschrist.org)", "ord": 62}, {"kind": "scripture", "body": "For behold, thus saith the Lord God: I will give unto the children of men line upon line, precept upon precept, here a little and there a little; and blessed are those who hearken unto my precepts, and lend an ear unto my counsel, for they shall learn wisdom; for unto him that receiveth I will give more; and from them that shall say, We have enough, from them shall be taken away even that which they have.", "citation": "2 Nephi 28:30", "url": "https://www.churchofjesuschrist.org/study/scriptures/bofm/2-ne/28?lang=eng&id=p30#p30", "source_note": "Book of Mormon (public-domain text, Project Gutenberg eBook #17; checked against churchofjesuschrist.org)", "ord": 63}, {"kind": "scripture", "body": "But to be learned is good if they hearken unto the counsels of God.", "citation": "2 Nephi 9:29", "url": "https://www.churchofjesuschrist.org/study/scriptures/bofm/2-ne/9?lang=eng&id=p29#p29", "source_note": "Book of Mormon (public-domain text, Project Gutenberg eBook #17; checked against churchofjesuschrist.org)", "ord": 64}, {"kind": "scripture", "body": "And it came to pass that I, Nephi, said unto my father: I will go and do the things which the Lord hath commanded, for I know that the Lord giveth no commandments unto the children of men, save he shall prepare a way for them that they may accomplish the thing which he commandeth them.", "citation": "1 Nephi 3:7", "url": "https://www.churchofjesuschrist.org/study/scriptures/bofm/1-ne/3?lang=eng&id=p7#p7", "source_note": "Book of Mormon (public-domain text, Project Gutenberg eBook #17; checked against churchofjesuschrist.org)", "ord": 65}, {"kind": "scripture", "body": "Yea, and are willing to mourn with those that mourn; yea, and comfort those that stand in need of comfort, and to stand as witnesses of God at all times and in all things, and in all places that ye may be in, even until death, that ye may be redeemed of God, and be numbered with those of the first resurrection, that ye may have eternal life—", "citation": "Mosiah 18:9", "url": "https://www.churchofjesuschrist.org/study/scriptures/bofm/mosiah/18?lang=eng&id=p9#p9", "source_note": "Book of Mormon (public-domain text, Project Gutenberg eBook #17; checked against churchofjesuschrist.org)", "ord": 66}, {"kind": "scripture", "body": "For where your treasure is, there will your heart be also.", "citation": "3 Nephi 13:21", "url": "https://www.churchofjesuschrist.org/study/scriptures/bofm/3-ne/13?lang=eng&id=p21#p21", "source_note": "Book of Mormon (public-domain text, Project Gutenberg eBook #17; checked against churchofjesuschrist.org)", "ord": 67}, {"kind": "scripture", "body": "And it came to pass that there was no contention in the land, because of the love of God which did dwell in the hearts of the people.", "citation": "4 Nephi 1:15", "url": "https://www.churchofjesuschrist.org/study/scriptures/bofm/4-ne/1?lang=eng&id=p15#p15", "source_note": "Book of Mormon (public-domain text, Project Gutenberg eBook #17; checked against churchofjesuschrist.org)", "ord": 68}, {"kind": "scripture", "body": "And blessed are all the peacemakers, for they shall be called the children of God.", "citation": "3 Nephi 12:9", "url": "https://www.churchofjesuschrist.org/study/scriptures/bofm/3-ne/12?lang=eng&id=p9#p9", "source_note": "Book of Mormon (public-domain text, Project Gutenberg eBook #17; checked against churchofjesuschrist.org)", "ord": 69}, {"kind": "scripture", "body": "And see that all these things are done in wisdom and order; for it is not requisite that a man should run faster than he has strength. And again, it is expedient that he should be diligent, that thereby he might win the prize; therefore, all things must be done in order.", "citation": "Mosiah 4:27", "url": "https://www.churchofjesuschrist.org/study/scriptures/bofm/mosiah/4?lang=eng&id=p27#p27", "source_note": "Book of Mormon (public-domain text, Project Gutenberg eBook #17; checked against churchofjesuschrist.org)", "ord": 70}, {"kind": "scripture", "body": "For none of these iniquities come of the Lord; for he doeth that which is good among the children of men; and he doeth nothing save it be plain unto the children of men; and he inviteth them all to come unto him and partake of his goodness; and he denieth none that come unto him, black and white, bond and free, male and female; and he remembereth the heathen; and all are alike unto God, both Jew and Gentile.", "citation": "2 Nephi 26:33", "url": "https://www.churchofjesuschrist.org/study/scriptures/bofm/2-ne/26?lang=eng&id=p33#p33", "source_note": "Book of Mormon (public-domain text, Project Gutenberg eBook #17; checked against churchofjesuschrist.org)", "ord": 71}, {"kind": "scripture", "body": "Wherefore, whoso believeth in God might with surety hope for a better world, yea, even a place at the right hand of God, which hope cometh of faith, maketh an anchor to the souls of men, which would make them sure and steadfast, always abounding in good works, being led to glorify God.", "citation": "Ether 12:4", "url": "https://www.churchofjesuschrist.org/study/scriptures/bofm/ether/12?lang=eng&id=p4#p4", "source_note": "Book of Mormon (public-domain text, Project Gutenberg eBook #17; checked against churchofjesuschrist.org)", "ord": 72}, {"kind": "scripture", "body": "Behold, I say unto you that whoso believeth in Christ, doubting nothing, whatsoever he shall ask the Father in the name of Christ it shall be granted him; and this promise is unto all, even unto the ends of the earth.", "citation": "Mormon 9:21", "url": "https://www.churchofjesuschrist.org/study/scriptures/bofm/morm/9?lang=eng&id=p21#p21", "source_note": "Book of Mormon (public-domain text, Project Gutenberg eBook #17; checked against churchofjesuschrist.org)", "ord": 73}, {"kind": "scripture", "body": "For behold, this life is the time for men to prepare to meet God; yea, behold the day of this life is the day for men to perform their labors.", "citation": "Alma 34:32", "url": "https://www.churchofjesuschrist.org/study/scriptures/bofm/alma/34?lang=eng&id=p32#p32", "source_note": "Book of Mormon (public-domain text, Project Gutenberg eBook #17; checked against churchofjesuschrist.org)", "ord": 74}, {"kind": "scripture", "body": "Wherefore, ye must press forward with a steadfastness in Christ, having a perfect brightness of hope, and a love of God and of all men. Wherefore, if ye shall press forward, feasting upon the word of Christ, and endure to the end, behold, thus saith the Father: Ye shall have eternal life.", "citation": "2 Nephi 31:20", "url": "https://www.churchofjesuschrist.org/study/scriptures/bofm/2-ne/31?lang=eng&id=p20#p20", "source_note": "Book of Mormon (public-domain text, Project Gutenberg eBook #17; checked against churchofjesuschrist.org)", "ord": 75}, {"kind": "conference", "body": "Spiritual growth is rarely dramatic at the beginning. Like an exponential curve, it often starts gradually—with loving parents, simple prayers, and small acts of faith.", "speaker": "President Dieter F. Uchtdorf", "speaker_role": "Acting President of the Quorum of the Twelve Apostles", "talk_title": "Christ-Centered Unity", "url": "https://www.churchofjesuschrist.org/study/general-conference/2026/10/51uchtdorf?lang=eng", "conference": "October 2026 General Conference", "ord": 76}, {"kind": "conference", "body": "God’s answer implies that experience is valuable, and I’m learning the only way to get it is to go through it. Can’t we skip over it? Is there some other way? No, there isn’t another way.", "speaker": "Sister Tamara W. Runia", "speaker_role": "First Counselor in the Young Women General Presidency", "talk_title": "The Sculpting of Our Souls", "url": "https://www.churchofjesuschrist.org/study/general-conference/2026/10/13runia?lang=eng", "conference": "October 2026 General Conference", "ord": 77}, {"kind": "conference", "body": "Being His true disciple, overcoming the world, keeping His commandments, and trusting in Him and His promises are not casual pursuits. Spiritual courage is the triumph over obstacles, doubt, and fear in choosing the right.", "speaker": "Elder Neil L. Andersen", "speaker_role": "Of the Quorum of the Twelve Apostles", "talk_title": "Courage Born of Our Faith in Jesus Christ", "url": "https://www.churchofjesuschrist.org/study/general-conference/2026/10/43andersen?lang=eng", "conference": "October 2026 General Conference", "ord": 78}, {"kind": "conference", "body": "Study the scriptures with a desire to know God’s character so you can do His will, increase your love for Him, and advance His work.", "speaker": "Sister Andrea Muñoz Spannaus", "speaker_role": "Second Counselor in the Young Women General Presidency", "talk_title": "God Is at Your Side", "url": "https://www.churchofjesuschrist.org/study/general-conference/2026/10/52munoz-spannaus?lang=eng", "conference": "October 2026 General Conference", "ord": 79}, {"kind": "conference", "body": "It is through covenants that we become yoked with the Savior Jesus Christ and our burdens become lighter.", "speaker": "Elder Ciro Schmeil", "speaker_role": "Of the Seventy", "talk_title": "Consider Your Ways, and from This Day Will the Lord Bless You", "url": "https://www.churchofjesuschrist.org/study/general-conference/2026/10/48schmeil?lang=eng", "conference": "October 2026 General Conference", "ord": 80}, {"kind": "conference", "body": "The Savior promised, “Peace I leave with you, my peace I give unto you.” This peace is real. It is powerful, and it begins with us—with our hearts, our choices, and our words.", "speaker": "Elder Alfred Kyungu", "speaker_role": "Of the Seventy", "talk_title": "Using the Language of Peacemakers", "url": "https://www.churchofjesuschrist.org/study/general-conference/2026/10/47kyungu?lang=eng", "conference": "October 2026 General Conference", "ord": 81}, {"kind": "conference", "body": "As we now go forward, we invoke the blessings of the Lord on you and your families, blessings of peace and contentment. And we bless your service of the Lord Jesus Christ in these challenging times.", "speaker": "President Dallin H. Oaks", "speaker_role": "President of The Church of Jesus Christ of Latter-day Saints", "talk_title": "Closing Remarks", "url": "https://www.churchofjesuschrist.org/study/general-conference/2026/10/510oaks?lang=eng", "conference": "October 2026 General Conference", "ord": 82}, {"kind": "conference", "body": "The Lord wants us to experience the joy of a virtuous life. He provides us with many beautiful gifts both physical and spiritual. Those who make sacrifices in His name will be richly rewarded.", "speaker": "Elder Quentin L. Cook", "speaker_role": "Of the Quorum of the Twelve Apostles", "talk_title": "Integrity and Virtue Lead to Happiness", "url": "https://www.churchofjesuschrist.org/study/general-conference/2026/10/46cook?lang=eng", "conference": "October 2026 General Conference", "ord": 83}, {"kind": "conference", "body": "Jesus Christ has the power to change us—you and me—purify us, and unite us. The closer we come to Him, the closer we will come to each other—and the closer we will come to the unity He wants for us.", "speaker": "President Dieter F. Uchtdorf", "speaker_role": "Acting President of the Quorum of the Twelve Apostles", "talk_title": "Christ-Centered Unity", "url": "https://www.churchofjesuschrist.org/study/general-conference/2026/10/51uchtdorf?lang=eng", "conference": "October 2026 General Conference", "ord": 84}, {"kind": "conference", "body": "The lesson I learned is this: No time or effort is ever wasted in reading the Book of Mormon. Not for you, not for your children, not for your family, not for anyone.", "speaker": "Elder Jeremiah J. Morgan", "speaker_role": "Of the Seventy", "talk_title": "The Infinite Power of God in Our Covenants", "url": "https://www.churchofjesuschrist.org/study/general-conference/2026/10/25morgan?lang=eng", "conference": "October 2026 General Conference", "ord": 85}, {"kind": "conference", "body": "The Lord invites all of us to teach His gospel. Wherever we teach—in classrooms, in the mission field, in our homes, or one by one—His promise remains the same: He will help us do His work.", "speaker": "Brother Gabriel W. Reid", "speaker_role": "Second Counselor in the Sunday School General Presidency", "talk_title": "You Are Good Enough to Teach", "url": "https://www.churchofjesuschrist.org/study/general-conference/2026/10/58reid?lang=eng", "conference": "October 2026 General Conference", "ord": 86}, {"kind": "conference", "body": "I am a child of God and He loves me. This statement is powerful and empowering. More importantly, it is true, not just for me but for each of us and all of us.", "speaker": "Elder Hutch U. Fale", "speaker_role": "Of the Seventy", "talk_title": "I Am a Child of God", "url": "https://www.churchofjesuschrist.org/study/general-conference/2026/10/26fale?lang=eng", "conference": "October 2026 General Conference", "ord": 87}, {"kind": "conference", "body": "For disciples of Jesus Christ, receiving priesthood ordinances and entering into sacred covenants are essential steps in the “quest of a lifetime” to align our hearts, minds, and lives with God’s will.", "speaker": "Elder David A. Bednar", "speaker_role": "Of the Quorum of the Twelve Apostles", "talk_title": "Sealed by the Holy Spirit of Promise", "url": "https://www.churchofjesuschrist.org/study/general-conference/2026/10/54bednar?lang=eng", "conference": "October 2026 General Conference", "ord": 88}, {"kind": "conference", "body": "Our testimony is not a talent to be hidden. It is a gift to be shared—with grateful hearts and in a spirit of humility and love.", "speaker": "Elder Gérald Caussé", "speaker_role": "Of the Quorum of the Twelve Apostles", "talk_title": "The Gift of Testimony", "url": "https://www.churchofjesuschrist.org/study/general-conference/2026/10/14causse?lang=eng", "conference": "October 2026 General Conference", "ord": 89}, {"kind": "conference", "body": "As we wait upon the Lord and exercise faith in Him, needed growth and spiritual stretching come, and the Savior delivers us from our afflictions and consecrates them for our gain. He does this in His time and way.", "speaker": "Elder Kevin J. Hathaway", "speaker_role": "Of the Seventy", "talk_title": "Jesus Christ Is the Great Deliverer!", "url": "https://www.churchofjesuschrist.org/study/general-conference/2026/10/16hathaway?lang=eng", "conference": "October 2026 General Conference", "ord": 90}, {"kind": "conference", "body": "Jesus Christ can bring light in our moments of darkness and restore hope where there is hopelessness. He knows where we have been, where we are, and where we need to be. Through Him, today can be a new day and tomorrow can be a better day.", "speaker": "Elder Thabo Lebethoa", "speaker_role": "Of the Seventy", "talk_title": "Jesus Christ Is the Light and Life of the World", "url": "https://www.churchofjesuschrist.org/study/general-conference/2026/10/55lebethoa?lang=eng", "conference": "October 2026 General Conference", "ord": 91}, {"kind": "conference", "body": "Before the Savior taught His disciples where to go and what to teach, He taught them who to become. His first lesson was not about teaching—it was about discipleship.", "speaker": "Brother Gabriel W. Reid", "speaker_role": "Second Counselor in the Sunday School General Presidency", "talk_title": "You Are Good Enough to Teach", "url": "https://www.churchofjesuschrist.org/study/general-conference/2026/10/58reid?lang=eng", "conference": "October 2026 General Conference", "ord": 92}, {"kind": "conference", "body": "Your testimony may be different from mine or that of other family members or fellow Saints. Please trust it, nurture it, and bear it, because it is uniquely yours.", "speaker": "Elder Gérald Caussé", "speaker_role": "Of the Quorum of the Twelve Apostles", "talk_title": "The Gift of Testimony", "url": "https://www.churchofjesuschrist.org/study/general-conference/2026/10/14causse?lang=eng", "conference": "October 2026 General Conference", "ord": 93}, {"kind": "conference", "body": "The gospel isn’t the umbrella; it’s the solid rock we’re standing on during the storm—that “sure foundation … whereon if men build they cannot fall.”", "speaker": "Sister Tamara W. Runia", "speaker_role": "First Counselor in the Young Women General Presidency", "talk_title": "The Sculpting of Our Souls", "url": "https://www.churchofjesuschrist.org/study/general-conference/2026/10/13runia?lang=eng", "conference": "October 2026 General Conference", "ord": 94}, {"kind": "conference", "body": "In a world of commotion, contention, and cares, the Lord invites us to a place of spiritual safety, harmony, and holiness—the house of the Lord.", "speaker": "Elder Gerrit W. Gong", "speaker_role": "Of the Quorum of the Twelve Apostles", "talk_title": "Come to the Lord in His Holy House", "url": "https://www.churchofjesuschrist.org/study/general-conference/2026/10/12gong?lang=eng", "conference": "October 2026 General Conference", "ord": 95}, {"kind": "conference", "body": "As we reflect on the great things the Lord has already done and remember His goodness and mercy, we are better positioned to grasp the bigger picture and to rely on His promises to us. We can trust Him.", "speaker": "Elder Dale G. Renlund", "speaker_role": "Of the Quorum of the Twelve Apostles", "talk_title": "“How Long Will It Be Ere They Believe Me?”", "url": "https://www.churchofjesuschrist.org/study/general-conference/2026/10/21renlund?lang=eng", "conference": "October 2026 General Conference", "ord": 96}, {"kind": "conference", "body": "Daily, meaningful scripture study invites the guidance of the Holy Ghost and builds our faith to face the temptations and the troubles of the world.", "speaker": "Elder Christian C. Chigbundu", "speaker_role": "Of the Seventy", "talk_title": "Spiritual Immunity", "url": "https://www.churchofjesuschrist.org/study/general-conference/2026/10/23chigbundu?lang=eng", "conference": "October 2026 General Conference", "ord": 97}, {"kind": "conference", "body": "You have a testimony of Jesus Christ and His Atonement that can bless a world suffering without knowledge of His divine mission. I pray that you will make the Savior’s grand commission your very own.", "speaker": "Bishop Sean Douglas", "speaker_role": "Second Counselor in the Presiding Bishopric", "talk_title": "The Hour of Your Mission Is Come", "url": "https://www.churchofjesuschrist.org/study/general-conference/2026/10/18douglas?lang=eng", "conference": "October 2026 General Conference", "ord": 98}, {"kind": "conference", "body": "Among the myriad nearly incomprehensible blessings of our Savior Jesus Christ is His promise to carry our burdens. But what does that look like in practical terms—especially when we are weighed down and seemingly without hope?", "speaker": "Elder Michael A. Dunn", "speaker_role": "Of the Seventy", "talk_title": "The Ninety and Ten", "url": "https://www.churchofjesuschrist.org/study/general-conference/2026/10/28dunn?lang=eng", "conference": "October 2026 General Conference", "ord": 99}, {"kind": "conference", "body": "At the heart of our faith is the glorious truth that we have an adoring Father in Heaven, whose Son, our Saviour, loves to lift!", "speaker": "Elder Patrick Kearon", "speaker_role": "Of the Quorum of the Twelve Apostles", "talk_title": "Jesus Lives to Lift", "url": "https://www.churchofjesuschrist.org/study/general-conference/2026/10/27kearon?lang=eng", "conference": "October 2026 General Conference", "ord": 100}, {"kind": "conference", "body": "We know that the Lord will comfort all of those who try to follow Him. And He offers us the great blessing and trust to help Him keep His promise to succor Heavenly Father’s children in their tests along their mortal journey toward home.", "speaker": "President Henry B. Eyring", "speaker_role": "First Counselor in the First Presidency", "talk_title": "“Fear Not, I Am with Thee”", "url": "https://www.churchofjesuschrist.org/study/general-conference/2026/10/41eyring?lang=eng", "conference": "October 2026 General Conference", "ord": 101}, {"kind": "conference", "body": "This invitation to forgo contention by using the language of peacemakers comes from the living prophet. It is not a simple suggestion; it is a call to discipleship as we follow Jesus Christ.", "speaker": "Elder Alfred Kyungu", "speaker_role": "Of the Seventy", "talk_title": "Using the Language of Peacemakers", "url": "https://www.churchofjesuschrist.org/study/general-conference/2026/10/47kyungu?lang=eng", "conference": "October 2026 General Conference", "ord": 102}, {"kind": "conference", "body": "I have developed the gift of gratitude by learning to appreciate the Lord’s hand in each of His tender mercies.", "speaker": "Elder Moisés Villanueva", "speaker_role": "Of the Seventy", "talk_title": "“Prove Me Now Herewith”", "url": "https://www.churchofjesuschrist.org/study/general-conference/2026/10/53villanueva?lang=eng", "conference": "October 2026 General Conference", "ord": 103}, {"kind": "conference", "body": "We do not need to perfect ourselves to come to Christ. We come to Christ to be perfected.", "speaker": "Elder Edward Dube", "speaker_role": "Of the Presidency of the Seventy", "talk_title": "Come unto Christ", "url": "https://www.churchofjesuschrist.org/study/general-conference/2026/10/45dube?lang=eng", "conference": "October 2026 General Conference", "ord": 104}, {"kind": "conference", "body": "Sometimes we expect the Lord’s blessings to come the way we would wish, rather than in His own way and timing.", "speaker": "Elder Moisés Villanueva", "speaker_role": "Of the Seventy", "talk_title": "“Prove Me Now Herewith”", "url": "https://www.churchofjesuschrist.org/study/general-conference/2026/10/53villanueva?lang=eng", "conference": "October 2026 General Conference", "ord": 105}, {"kind": "conference", "body": "Replace worldly labels with these eternal truths: Child of God. Child of the covenant. Disciple of Jesus Christ.", "speaker": "President Rosemary K. Chibota", "speaker_role": "Primary General President", "talk_title": "A Child of God", "url": "https://www.churchofjesuschrist.org/study/general-conference/2026/10/42chibota?lang=eng", "conference": "October 2026 General Conference", "ord": 106}, {"kind": "conference", "body": "As we choose faith in Christ, He blesses us with the courage, sometimes in very difficult situations, to choose the right, and as we manifest our courage to choose the right, our faith in Christ strengthens.", "speaker": "Elder Neil L. Andersen", "speaker_role": "Of the Quorum of the Twelve Apostles", "talk_title": "Courage Born of Our Faith in Jesus Christ", "url": "https://www.churchofjesuschrist.org/study/general-conference/2026/10/43andersen?lang=eng", "conference": "October 2026 General Conference", "ord": 107}, {"kind": "conference", "body": "The Book of Mormon is a great witness that the Lord loves all people and reaches out to all, everywhere.", "speaker": "President Dallin H. Oaks", "speaker_role": "President of The Church of Jesus Christ of Latter-day Saints", "talk_title": "The Gospel of Jesus Christ Is for All", "url": "https://www.churchofjesuschrist.org/study/general-conference/2026/10/49oaks?lang=eng", "conference": "October 2026 General Conference", "ord": 108}, {"kind": "conference", "body": "Whatever labels may weigh heavily upon you today, Jesus Christ can raise you above them. His grace is sufficient to lift you above every label and limitation.", "speaker": "President Rosemary K. Chibota", "speaker_role": "Primary General President", "talk_title": "A Child of God", "url": "https://www.churchofjesuschrist.org/study/general-conference/2026/10/42chibota?lang=eng", "conference": "October 2026 General Conference", "ord": 109}, {"kind": "conference", "body": "When we try to love others by minimizing God’s laws, we separate ourselves from the one person who loves them the very most. The Savior showed love for the woman taken in adultery. But He also charged her to “go, and sin no more.”", "speaker": "Elder Clark G. Gilbert", "speaker_role": "Of the Quorum of the Twelve Apostles", "talk_title": "Teach Truth with Love", "url": "https://www.churchofjesuschrist.org/study/general-conference/2026/10/59gilbert?lang=eng", "conference": "October 2026 General Conference", "ord": 110}, {"kind": "conference", "body": "Wherever you are, I invite you to join the Christ-centered unity we are trying to build. It would be incomplete without you. Please, come and see, come and help, and come and belong.", "speaker": "President Dieter F. Uchtdorf", "speaker_role": "Acting President of the Quorum of the Twelve Apostles", "talk_title": "Christ-Centered Unity", "url": "https://www.churchofjesuschrist.org/study/general-conference/2026/10/51uchtdorf?lang=eng", "conference": "October 2026 General Conference", "ord": 111}, {"kind": "conference", "body": "He has already paid for the sins and errant choices of all of God’s children, including those for whom you and I grieve. He knows them. He knows their hearts; He loves them. He gave His very life to bring them home, all the way home.", "speaker": "Elder Ronald A. Rasband", "speaker_role": "Of the Quorum of the Twelve Apostles", "talk_title": "Love Like Jesus", "url": "https://www.churchofjesuschrist.org/study/general-conference/2026/10/210rasband?lang=eng", "conference": "October 2026 General Conference", "ord": 112}, {"kind": "conference", "body": "Someday we will more fully realize how generous and kind the Lord has been to each of us. We will better understand and appreciate the depth of the Savior’s sacrifice and the reality that He and the Father are truly givers of good gifts.", "speaker": "Elder Matthew J. Eyring", "speaker_role": "Of the Seventy", "talk_title": "Comfort from the Holy Ghost", "url": "https://www.churchofjesuschrist.org/study/general-conference/2026/10/29eyring?lang=eng", "conference": "October 2026 General Conference", "ord": 113}, {"kind": "conference", "body": "Our Father and our Savior know you and have the same perfect love for you. Part of that love and mercy is giving us many opportunities and being patient as we learn and work on our list of aspirations.", "speaker": "Sister Andrea Muñoz Spannaus", "speaker_role": "Second Counselor in the Young Women General Presidency", "talk_title": "God Is at Your Side", "url": "https://www.churchofjesuschrist.org/study/general-conference/2026/10/52munoz-spannaus?lang=eng", "conference": "October 2026 General Conference", "ord": 114}, {"kind": "book", "body": "Every action you take is a vote for the type of person you wish to become. No single instance will transform your beliefs, but as the votes build up, so does the evidence of your new identity.", "book": "Atomic Habits", "source_note": "Wording matched on Goodreads and at least one independent quote source", "ord": 115}, {"kind": "book", "body": "You don’t need to map out every feature of a new habit. You just need to practice it.", "book": "Atomic Habits", "source_note": "Wording matched on Goodreads and at least one independent quote source", "ord": 116}, {"kind": "book", "body": "But I learned that good leaders don’t make excuses. Instead, they figure out a way to get it done and win.", "book": "Extreme Ownership", "source_note": "Wording matched on Goodreads and at least one independent quote source", "ord": 117}, {"kind": "book", "body": "Success is the product of daily habits—not once-in-a-lifetime transformations.", "book": "Atomic Habits", "source_note": "Wording matched on Goodreads and at least one independent quote source", "ord": 118}, {"kind": "book", "body": "The most important ingredient we put into any relationship is not what we say or what we do, but what we are.", "book": "The 7 Habits of Highly Effective People", "source_note": "Wording matched on Goodreads and at least one independent quote source", "ord": 119}, {"kind": "book", "body": "When we open our mouths to describe what we see, we in effect describe ourselves, our perceptions, our paradigms.", "book": "The 7 Habits of Highly Effective People", "source_note": "Wording matched on Goodreads and at least one independent quote source", "ord": 120}, {"kind": "book", "body": "If I really want to improve my situation, I can work on the one thing over which I have control — myself.", "book": "The 7 Habits of Highly Effective People", "source_note": "Wording matched on Goodreads and at least one independent quote source", "ord": 121}, {"kind": "book", "body": "Progress requires unlearning. Becoming the best version of yourself requires you to continuously edit your beliefs, and to upgrade and expand your identity.", "book": "Atomic Habits", "source_note": "Wording matched on Goodreads and at least one independent quote source", "ord": 122}, {"kind": "book", "body": "The task of breaking a bad habit is like uprooting a powerful oak within us. And the task of building a good habit is like cultivating a delicate flower one day at a time.", "book": "Atomic Habits", "source_note": "Wording matched on Goodreads and at least one independent quote source", "ord": 123}, {"kind": "book", "body": "Habits are the compound interest of self-improvement.", "book": "Atomic Habits", "source_note": "Wording matched on Goodreads and at least one independent quote source", "ord": 124}, {"kind": "book", "body": "In the last analysis, what we are communicates far more eloquently than anything we say or do.", "book": "The 7 Habits of Highly Effective People", "source_note": "Wording matched on Goodreads and at least one independent quote source", "ord": 125}, {"kind": "book", "body": "Be the designer of your world and not merely the consumer of it.", "book": "Atomic Habits", "source_note": "Wording matched on Goodreads and at least one independent quote source", "ord": 126}, {"kind": "book", "body": "Be a light, not a judge. Be a model, not a critic.", "book": "The 7 Habits of Highly Effective People", "source_note": "Wording matched on Goodreads and at least one independent quote source", "ord": 127}, {"kind": "book", "body": "If you want better results, then forget about setting goals. Focus on your system instead.", "book": "Atomic Habits", "source_note": "Wording matched on Goodreads and at least one independent quote source", "ord": 128}, {"kind": "book", "body": "Even the most competent of leaders can be overwhelmed if they try to tackle multiple problems or a number of tasks simultaneously.", "book": "Extreme Ownership", "source_note": "Wording matched on Goodreads and at least one independent quote source", "ord": 129}, {"kind": "book", "body": "People get so caught up in the fact that they have limits that they rarely exert the effort required to get close to them.", "book": "Atomic Habits", "source_note": "Wording matched on Goodreads and at least one independent quote source", "ord": 130}, {"kind": "book", "body": "We don’t choose our earliest habits, we imitate them.", "book": "Atomic Habits", "source_note": "Wording matched on Goodreads and at least one independent quote source", "ord": 131}, {"kind": "book", "body": "A leader must lead but also be ready to follow.", "book": "Extreme Ownership", "source_note": "Wording matched on Goodreads and at least one independent quote source", "ord": 132}, {"kind": "book", "body": "Your clutter is a lagging measure of your cleaning habits. You get what you repeat.", "book": "Atomic Habits", "source_note": "Wording matched on Goodreads and at least one independent quote source", "ord": 133}, {"kind": "book", "body": "You can’t make people listen to you. You can’t make them execute.", "book": "Extreme Ownership", "source_note": "Wording matched on Goodreads and at least one independent quote source", "ord": 134}, {"kind": "book", "body": "If you adopt a pattern of life that focuses on golden eggs and neglects the goose, you will soon be without the asset that produces golden eggs.", "book": "The 7 Habits of Highly Effective People", "source_note": "Wording matched on Goodreads and at least one independent quote source", "ord": 135}, {"kind": "book", "body": "You do not rise to the level of your goals. You fall to the level of your systems.", "book": "Atomic Habits", "source_note": "Wording matched on Goodreads and at least one independent quote source", "ord": 136}, {"kind": "book", "body": "We learned that leadership requires belief in the mission and unyielding perseverance to achieve victory, particularly when doubters question whether victory is even possible.", "book": "Extreme Ownership", "source_note": "Wording matched on Goodreads and at least one independent quote source", "ord": 137}, {"kind": "book", "body": "There is no one else to blame. The leader must acknowledge mistakes and admit failures, take ownership of them, and develop a plan to win.", "book": "Extreme Ownership", "source_note": "Wording matched on Goodreads and at least one independent quote source", "ord": 138}, {"kind": "book", "body": "The best leaders are not driven by ego or personal agendas. They are simply focused on the mission and how best to accomplish it.", "book": "Extreme Ownership", "source_note": "Wording matched on Goodreads and at least one independent quote source", "ord": 139}, {"kind": "book", "body": "Waiting for the 100 percent right and certain solution leads to delay, indecision, and an inability to execute.", "book": "Extreme Ownership", "source_note": "Wording matched on Goodreads and at least one independent quote source", "ord": 140}, {"kind": "book", "body": "The only meaningful measure for a leader is whether the team succeeds or fails. For all the definitions, descriptions, and characterizations of leaders, there are only two that matter: effective and ineffective.", "book": "Extreme Ownership", "source_note": "Wording matched on Goodreads and at least one independent quote source", "ord": 141}, {"kind": "book", "body": "When the trust account is high, communication is easy, instant, and effective.", "book": "The 7 Habits of Highly Effective People", "source_note": "Wording matched on Goodreads and at least one independent quote source", "ord": 142}, {"kind": "book", "body": "The only way you could make time, was to get up early. That took discipline.", "book": "Extreme Ownership", "source_note": "Wording matched on Goodreads and at least one independent quote source", "ord": 143}, {"kind": "book", "body": "Love — the feeling — is a fruit of love, the verb.", "book": "The 7 Habits of Highly Effective People", "source_note": "Wording matched on Goodreads and at least one independent quote source", "ord": 144}, {"kind": "book", "body": "Implementing Extreme Ownership requires checking your ego and operating with a high degree of humility.", "book": "Extreme Ownership", "source_note": "Wording matched on Goodreads and at least one independent quote source", "ord": 145}, {"kind": "book", "body": "If you’re having trouble changing your habits, the problem isn’t you. The problem is your system.", "book": "Atomic Habits", "source_note": "Wording matched on Goodreads and at least one independent quote source", "ord": 146}, {"kind": "book", "body": "Leadership isn’t one person leading a team. It is a group of leaders working together, up and down the chain of command, to lead.", "book": "Extreme Ownership", "source_note": "Wording matched on Goodreads and at least one independent quote source", "ord": 147}, {"kind": "book", "body": "Be patient with yourself. Self-growth is tender; it’s holy ground.", "book": "The 7 Habits of Highly Effective People", "source_note": "Wording matched on Goodreads and at least one independent quote source", "ord": 148}, {"kind": "book", "body": "The goal of all leaders should be to work themselves out of a job. This means leaders must be heavily engaged in training and mentoring their junior leaders to prepare them to step up and assume greater responsibilities.", "book": "Extreme Ownership", "source_note": "Wording matched on Goodreads and at least one independent quote source", "ord": 149}, {"kind": "book", "body": "Getting 1 percent better every day counts for a lot in the long-run.", "book": "Atomic Habits", "source_note": "Wording matched on Goodreads and at least one independent quote source", "ord": 150}, {"kind": "book", "body": "Leaders must own everything in their world. There is no one else to blame.", "book": "Extreme Ownership", "source_note": "Wording matched on Goodreads and at least one independent quote source", "ord": 151}, {"kind": "book", "body": "The leader’s attitude sets the tone for the entire team. The leader drives performance—or doesn’t.", "book": "Extreme Ownership", "source_note": "Wording matched on Goodreads and at least one independent quote source", "ord": 152}, {"kind": "book", "body": "A lack of self-awareness is poison. Reflection and review is the antidote.", "book": "Atomic Habits", "source_note": "Wording matched on Goodreads and at least one independent quote source", "ord": 153}, {"kind": "book", "body": "Whether a team succeeds or fails is all up to the leader. The leader’s attitude sets the tone for the entire team.", "book": "Extreme Ownership", "source_note": "Wording matched on Goodreads and at least one independent quote source", "ord": 154}, {"kind": "book", "body": "On any team, in any organization, all responsibility for success and failure rests with the leader. The leader must own everything in his or her world.", "book": "Extreme Ownership", "source_note": "Wording matched on Goodreads and at least one independent quote source", "ord": 155}, {"kind": "book", "body": "All big things come from small beginnings. The seed of every habit is a single, tiny decision.", "book": "Atomic Habits", "source_note": "Wording matched on Goodreads and at least one independent quote source", "ord": 156}, {"kind": "book", "body": "A good leader has nothing to prove, but everything to prove.", "book": "Extreme Ownership", "source_note": "Wording matched on Goodreads and at least one independent quote source", "ord": 157}, {"kind": "book", "body": "Once people stop making excuses, stop blaming others, and take ownership of everything in their lives, they are compelled to take action to solve their problems.", "book": "Extreme Ownership", "source_note": "Wording matched on Goodreads and at least one independent quote source", "ord": 158}, {"kind": "book", "body": "Your actions reveal how badly you want something. If you keep saying something is a priority but you never act on it, then you don’t really want it.", "book": "Atomic Habits", "source_note": "Wording matched on Goodreads and at least one independent quote source", "ord": 159}, {"kind": "book", "body": "Don’t ask your leader what you should do, tell them what you are going to do.", "book": "Extreme Ownership", "source_note": "Wording matched on Goodreads and at least one independent quote source", "ord": 160}, {"kind": "book", "body": "With outcome-based habits, the focus is on what you want to achieve. With identity-based habits, the focus is on who you wish to become.", "book": "Atomic Habits", "source_note": "Wording matched on Goodreads and at least one independent quote source", "ord": 161}, {"kind": "book", "body": "Although discipline demands control and asceticism, it actually results in freedom. When you have the discipline to get up early, you are rewarded with more free time.", "book": "Extreme Ownership", "source_note": "Wording matched on Goodreads and at least one independent quote source", "ord": 162}, {"kind": "book", "body": "If you want to master a habit, the key is to start with repetition, not perfection. You don’t need to map out every feature of a new habit.", "book": "Atomic Habits", "source_note": "Wording matched on Goodreads and at least one independent quote source", "ord": 163}, {"kind": "book", "body": "Professionals stick to the schedule; amateurs let life get in the way.", "book": "Atomic Habits", "source_note": "Wording matched on Goodreads and at least one independent quote source", "ord": 164}, {"kind": "book", "body": "The way we see the problem is the problem.", "book": "The 7 Habits of Highly Effective People", "source_note": "Wording matched on Goodreads and at least one independent quote source", "ord": 165}, {"kind": "book", "body": "Repetitive exceptional performance became a habit.", "book": "Extreme Ownership", "source_note": "Wording matched on Goodreads and at least one independent quote source", "ord": 166}, {"kind": "book", "body": "For leaders, the humility to admit and own mistakes and develop a plan to overcome them is essential to success. The best leaders are not driven by ego or personal agendas.", "book": "Extreme Ownership", "source_note": "Wording matched on Goodreads and at least one independent quote source", "ord": 167}, {"kind": "book", "body": "We all deal with setbacks but in the long run, the quality of our lives often depends on the quality of our habits.", "book": "Atomic Habits", "source_note": "Wording matched on Goodreads and at least one independent quote source", "ord": 168}, {"kind": "book", "body": "In order to improve for good, you need to solve problems at the systems level. Fix the inputs and the outputs will fix themselves.", "book": "Atomic Habits", "source_note": "Wording matched on Goodreads and at least one independent quote source", "ord": 169}, {"kind": "book", "body": "Our freedom to operate and maneuver had increased substantially through disciplined procedures. Discipline equals freedom.", "book": "Extreme Ownership", "source_note": "Wording matched on Goodreads and at least one independent quote source", "ord": 170}, {"kind": "book", "body": "Put another way, the costs of your good habits are in the present. The costs of your bad habits are in the future.", "book": "Atomic Habits", "source_note": "Wording matched on Goodreads and at least one independent quote source", "ord": 171}, {"kind": "book", "body": "Anyone can work hard when they feel motivated. It’s the ability to keep going when work isn’t exciting that makes the difference.", "book": "Atomic Habits", "source_note": "Wording matched on Goodreads and at least one independent quote source", "ord": 172}, {"kind": "book", "body": "It’s one thing to say I’m the type of person who wants this. It’s something very different to say I’m the type of person who is this.", "book": "Atomic Habits", "source_note": "Wording matched on Goodreads and at least one independent quote source", "ord": 173}, {"kind": "book", "body": "The greatest threat to success is not failure but boredom. We get bored with habits because they stop delighting us.", "book": "Atomic Habits", "source_note": "Wording matched on Goodreads and at least one independent quote source", "ord": 174}, {"kind": "book", "body": "Missing once is an accident. Missing twice is the start of a new habit.", "book": "Atomic Habits", "source_note": "Wording matched on Goodreads and at least one independent quote source", "ord": 175}, {"kind": "book", "body": "Remember, to learn and not to do is really not to learn.", "book": "The 7 Habits of Highly Effective People", "source_note": "Wording matched on Goodreads and at least one independent quote source", "ord": 176}, {"kind": "book", "body": "Instead of letting the situation dictate our decisions, we must dictate the situation.", "book": "Extreme Ownership", "source_note": "Wording matched on Goodreads and at least one independent quote source", "ord": 177}, {"kind": "book", "body": "Wisdom is your perspective on life, your sense of balance, your understanding of how the various parts and principles apply and relate to each other.", "book": "The 7 Habits of Highly Effective People", "source_note": "Wording matched on Goodreads and at least one independent quote source", "ord": 178}, {"kind": "book", "body": "Decide the type of person you want to be. Prove it to yourself with small wins.", "book": "Atomic Habits", "source_note": "Wording matched on Goodreads and at least one independent quote source", "ord": 179}, {"kind": "book", "body": "It is critical for leaders to act decisively amid uncertainty; to make the best decisions they can based on only the immediate information available.", "book": "Extreme Ownership", "source_note": "Wording matched on Goodreads and at least one independent quote source", "ord": 180}, {"kind": "book", "body": "To know and not to do is really not to know.", "book": "The 7 Habits of Highly Effective People", "source_note": "Wording matched on Goodreads and at least one independent quote source", "ord": 181}, {"kind": "book", "body": "You always reap what you sow; there is no shortcut.", "book": "The 7 Habits of Highly Effective People", "source_note": "Wording matched on Goodreads and at least one independent quote source", "ord": 182}, {"kind": "book", "body": "The purpose of setting goals is to win the game. The purpose of building systems is to continue playing the game.", "book": "Atomic Habits", "source_note": "Wording matched on Goodreads and at least one independent quote source", "ord": 183}, {"kind": "book", "body": "Goals are good for setting a direction, but systems are best for making progress.", "book": "Atomic Habits", "source_note": "Wording matched on Goodreads and at least one independent quote source", "ord": 184}, {"kind": "book", "body": "The key is not to prioritize what’s on your schedule, but to schedule your priorities.", "book": "The 7 Habits of Highly Effective People", "source_note": "Wording matched on Goodreads and at least one independent quote source", "ord": 185}, {"kind": "book", "body": "Leaders must always operate with the understanding that they are part of something greater than themselves and their own personal interests.", "book": "Extreme Ownership", "source_note": "Wording matched on Goodreads and at least one independent quote source", "ord": 186}, {"kind": "book", "body": "Effective leaders lead successful teams that accomplish their mission and win. Ineffective leaders do not.", "book": "Extreme Ownership", "source_note": "Wording matched on Goodreads and at least one independent quote source", "ord": 187}, {"kind": "book", "body": "Most people do not listen with the intent to understand; they listen with the intent to reply.", "book": "The 7 Habits of Highly Effective People", "source_note": "Wording matched on Goodreads and at least one independent quote source", "ord": 188}, {"kind": "book", "body": "Principles are the territory. Values are maps.", "book": "The 7 Habits of Highly Effective People", "source_note": "Wording matched on Goodreads and at least one independent quote source", "ord": 189}, {"kind": "book", "body": "We see the world, not as it is, but as we are—or, as we are conditioned to see it.", "book": "The 7 Habits of Highly Effective People", "source_note": "Wording matched on Goodreads and at least one independent quote source", "ord": 190}, {"kind": "book", "body": "Plans and orders must be communicated in a manner that is simple, clear, and concise.", "book": "Extreme Ownership", "source_note": "Wording matched on Goodreads and at least one independent quote source", "ord": 191}, {"kind": "book", "body": "There’s a mental or first creation, and a physical or second creation, to all things.", "book": "The 7 Habits of Highly Effective People", "source_note": "Wording matched on Goodreads and at least one independent quote source", "ord": 192}, {"kind": "book", "body": "The first mistake is never the one that ruins you.", "book": "Atomic Habits", "source_note": "Wording matched on Goodreads and at least one independent quote source", "ord": 193}, {"kind": "book", "body": "When you fall in love with the process rather than the product, you don’t have to wait to give yourself permission to be happy. You can be satisfied anytime your system is running.", "book": "Atomic Habits", "source_note": "Wording matched on Goodreads and at least one independent quote source", "ord": 194}, {"kind": "book", "body": "Almost no mission ever goes according to plan. There are simply too many variables to deal with.", "book": "Extreme Ownership", "source_note": "Wording matched on Goodreads and at least one independent quote source", "ord": 195}, {"kind": "book", "body": "Motivation is overrated, environment often matters more.", "book": "Atomic Habits", "source_note": "Wording matched on Goodreads and at least one independent quote source", "ord": 196}, {"kind": "book", "body": "Admitting mistakes, taking ownership, and developing a plan to overcome challenges are integral to any successful team.", "book": "Extreme Ownership", "source_note": "Wording matched on Goodreads and at least one independent quote source", "ord": 197}, {"kind": "book", "body": "The only way to become excellent is to be endlessly fascinated by doing the same thing over and over. You have to fall in love with boredom.", "book": "Atomic Habits", "source_note": "Wording matched on Goodreads and at least one independent quote source", "ord": 198}, {"kind": "book", "body": "Leadership is simple, but not easy.", "book": "Extreme Ownership", "source_note": "Wording matched on Goodreads and at least one independent quote source", "ord": 199}, {"kind": "book", "body": "Be part of the solution, not part of the problem.", "book": "The 7 Habits of Highly Effective People", "source_note": "Wording matched on Goodreads and at least one independent quote source", "ord": 200}, {"kind": "book", "body": "It’s not what you preach, it’s what you tolerate.", "book": "Extreme Ownership", "source_note": "Wording matched on Goodreads and at least one independent quote source", "ord": 201}, {"kind": "book", "body": "You don’t want to merely be planning. You want to be practicing.", "book": "Atomic Habits", "source_note": "Wording matched on Goodreads and at least one independent quote source", "ord": 202}, {"kind": "book", "body": "You should be far more concerned with your current trajectory than with your current results.", "book": "Atomic Habits", "source_note": "Wording matched on Goodreads and at least one independent quote source", "ord": 203}, {"kind": "book", "body": "Redesign your life so the actions that matter most are also the actions that are easiest to do.", "book": "Atomic Habits", "source_note": "Wording matched on Goodreads and at least one independent quote source", "ord": 204}, {"kind": "book", "body": "Some people spend their entire lives waiting for the time to be right to make an improvement.", "book": "Atomic Habits", "source_note": "Wording matched on Goodreads and at least one independent quote source", "ord": 205}, {"kind": "book", "body": "Leaders should never be satisfied. They must always strive to improve, and they must build that mind-set into the team.", "book": "Extreme Ownership", "source_note": "Wording matched on Goodreads and at least one independent quote source", "ord": 206}, {"kind": "book", "body": "The focus must always be on how to best accomplish the mission.", "book": "Extreme Ownership", "source_note": "Wording matched on Goodreads and at least one independent quote source", "ord": 207}, {"kind": "book", "body": "Simplifying as much as possible is crucial to success. When plans and orders are too complicated, people may not understand them.", "book": "Extreme Ownership", "source_note": "Wording matched on Goodreads and at least one independent quote source", "ord": 208}, {"kind": "book", "body": "Habits are like the atoms of our lives. Each one is a fundamental unit that contributes to your overall improvement.", "book": "Atomic Habits", "source_note": "Wording matched on Goodreads and at least one independent quote source", "ord": 209}, {"kind": "book", "body": "Look at the weaknesses of others with compassion, not accusation.", "book": "The 7 Habits of Highly Effective People", "source_note": "Wording matched on Goodreads and at least one independent quote source", "ord": 210}, {"kind": "book", "body": "When you make your bed each day, you embody the identity of an organized person. When you write each day, you embody the identity of a creative person.", "book": "Atomic Habits", "source_note": "Wording matched on Goodreads and at least one independent quote source", "ord": 211}]$seed$::jsonb) as r(kind text, body text, citation text, speaker text, speaker_role text, talk_title text, url text, conference text, book text, source_note text, ord bigint)
left join public.dl_books b on b.title = r.book and b.seeded
order by r.ord;
